<?php
session_start();
if (empty($_SESSION['stac_cms_logged_in'])) { header('Location: ./'); exit; }
$_SESSION['csrf'] ??= bin2hex(random_bytes(32));
$pageNames = stac_cms_editable_pages();
$selected = in_array($_GET['page'] ?? '', $pageNames, true) ? $_GET['page'] : 'index.php';
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage page images · STAC</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#edf2f7;color:#182b43;font:16px/1.5 system-ui,sans-serif}.wrap{max-width:1440px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}h1{margin:0;font-size:26px}.top a,a{color:#123b70}.intro{color:#516273;margin:0 0 20px}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:16px;background:#fff;border:1px solid #d8e1ea;border-radius:9px;margin-bottom:16px}.controls label{font-weight:650}.controls select{font:inherit;min-width:250px;padding:10px;border:1px solid #b9c8d7;border-radius:6px;background:#fff}.status{margin-left:auto;color:#23633d;font-weight:600}.status.error{color:#a3231b}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:16px}.card{min-width:0;overflow:hidden;background:#fff;border:1px solid #d8e1ea;border-radius:9px}.thumb{height:175px;background:#e2e8f0 center/cover no-repeat;display:grid;place-items:center;overflow:hidden}.thumb img{display:block;width:100%;height:100%;object-fit:cover}.thumb .placeholder{color:#516273;font-size:14px}.details{padding:13px}.section{display:block;margin-bottom:5px;color:#123b70;font-size:13px;font-weight:700}.filename{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#516273;font-size:13px}.alt{min-height:21px;margin:5px 0 12px;color:#344b62;font-size:14px}.card button{width:100%;padding:10px 12px;border:0;border-radius:6px;background:#123b70;color:white;font:inherit;font-weight:650;cursor:pointer}.card button:hover{background:#0d2d57}.card button:focus-visible,.controls select:focus-visible,a:focus-visible{outline:3px solid #78aee4;outline-offset:2px}.empty{padding:28px;background:#fff;border:1px solid #d8e1ea;border-radius:9px;color:#516273}.frame{position:fixed;left:-20000px;top:0;width:min(1280px,100vw);height:900px;visibility:hidden;pointer-events:none;border:0}@media(max-width:600px){.wrap{padding:14px}.top{align-items:flex-start;gap:12px}.controls{align-items:stretch}.controls select{width:100%;min-width:0}.status{margin-left:0;width:100%}}
</style><main class="wrap"><div class="top"><h1>Manage page images</h1><a href="./?page=<?= rawurlencode($selected) ?>">← Back to text editor</a></div>
<p class="intro">Choose a page to see its pictures and the section each belongs to. Replacing a picture saves the page automatically.</p>
<div class="controls"><label for="page">Page</label><select id="page"><?php foreach ($pageNames as $p): ?><option value="<?= htmlspecialchars($p) ?>" <?= $p === $selected ? 'selected' : '' ?>><?= htmlspecialchars(match($p) { 'index.php' => 'Home page', 'apply-to-kingster.php' => 'Apply Now', 'give-to-kingster.php' => 'Support Us', default => ucwords(str_replace(['-', '.php'], [' ', ''], $p)) }) ?></option><?php endforeach; ?></select><span class="status" id="status" role="status" aria-live="polite">Loading pictures…</span></div>
<div id="gallery" class="gallery" aria-live="polite"></div><input id="image-file" type="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden>
<iframe class="frame" id="preview" title="Page image source" src="preview.php?page=<?= rawurlencode($selected) ?>"></iframe></main>
<script>
const page=document.querySelector('#page'),frame=document.querySelector('#preview'),gallery=document.querySelector('#gallery'),status=document.querySelector('#status'),fileInput=document.querySelector('#image-file');
const csrf=<?= json_encode($_SESSION['csrf']) ?>;let inventory=[],selectedIndex=-1;
page.addEventListener('change',()=>location.href='images.php?page='+encodeURIComponent(page.value));
function sectionName(element,area){for(let node=element.parentElement;node&&node!==area;node=node.parentElement){const heading=node.querySelector('h1,h2,h3,h4,h5,h6');if(heading?.textContent.trim())return heading.textContent.trim();}return element.alt||element.title||'Page image';}
function imageUrl(element){if(element.tagName==='IMG')return element.currentSrc||element.src||element.getAttribute('data-src')||'';const match=getComputedStyle(element).backgroundImage.match(/url\(["']?(.*?)["']?\)/);return match?new URL(match[1],frame.contentDocument.baseURI).href:'';}
function renderGallery(){
 const doc=frame.contentDocument,area=doc?.querySelector('#stac-cms-edit-area');if(!area){status.className='status error';status.textContent='Could not load this page. Please refresh and try again.';return;}
 inventory=[];gallery.replaceChildren();
 const backgroundNodes=[...area.querySelectorAll('*')].filter(node=>getComputedStyle(node).backgroundImage.includes('url('));
 for(const element of [...new Set([...area.querySelectorAll('img'),...backgroundNodes])]){
  const url=imageUrl(element);if(!url||url.startsWith('data:'))continue;
  const index=inventory.length,section=sectionName(element,area);element.setAttribute('data-cms-gallery-index',String(index));
  inventory.push({element,url,section,alt:element.alt||element.title||'',background:element.tagName!=='IMG'});
  const card=document.createElement('article');card.className='card';const thumb=document.createElement('div');thumb.className='thumb';
  if(element.tagName==='IMG'){const image=document.createElement('img');image.src=url;image.alt=element.alt||'';image.loading='lazy';thumb.append(image);}else thumb.style.backgroundImage='url('+JSON.stringify(url)+')';
  const details=document.createElement('div');details.className='details';const label=document.createElement('span');label.className='section';label.textContent=section;const filename=document.createElement('span');filename.className='filename';filename.textContent=new URL(url).pathname.split('/').pop()||url;const alt=document.createElement('p');alt.className='alt';alt.textContent=inventory[index].alt?'Alt text: '+inventory[index].alt:(inventory[index].background?'Background picture':'No alt text');const button=document.createElement('button');button.type='button';button.textContent='Replace this picture';button.addEventListener('click',()=>{selectedIndex=index;fileInput.click();});
  details.append(label,filename,alt,button);card.append(thumb,details);gallery.append(card);
 }
 status.className='status';status.textContent=inventory.length?inventory.length+' pictures found. Replacing one saves automatically.':'No pictures were found on this page.';
}
frame.addEventListener('load',renderGallery);
fileInput.addEventListener('change',async()=>{const file=fileInput.files[0],item=inventory[selectedIndex];if(!file||!item)return;status.className='status';status.textContent='Uploading picture…';try{const form=new FormData();form.append('image',file);const response=await fetch('upload.php',{method:'POST',headers:{'X-CSRF-Token':csrf},body:form});const result=await response.json();if(!response.ok)throw new Error(result.error||'Picture upload failed.');if(item.background)item.element.style.backgroundImage='url('+JSON.stringify(new URL(result.url,location.origin).href)+')';else item.element.src=result.url;item.url=new URL(result.url,location.origin).href;status.textContent='Saving page…';frame.contentWindow.postMessage({type:'stac-cms-read-content'},location.origin);}catch(error){status.className='status error';status.textContent=error.message;}finally{fileInput.value='';}});
window.addEventListener('message',async event=>{if(event.origin!==location.origin||event.data?.type!=='stac-cms-content')return;try{const response=await fetch('save.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({page:page.value,content:event.data.content})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save this page.');status.className='status';status.textContent='Picture replaced and page saved.';}catch(error){status.className='status error';status.textContent=error.message;}});
</script></html>
